import{_ as e,b as l,c as o,I as a}from"./chunks/framework.C6cPs9Ia.js";const m=JSON.parse('{"title":"开站第一篇","description":"柳卿烟的博客开站第一篇——自我介绍与站点功能说明","frontmatter":{"title":"开站第一篇","date":"2026-09-15T00:00:00.000Z","tags":["建站","日常"],"cover":"/LQY/images/moment-1.jpg","head":[["meta",{"name":"description","content":"柳卿烟的博客开站第一篇——自我介绍与站点功能说明"}],["meta",{"name":"keywords","content":"建站, 博客, 开站, 自我介绍"}]]},"headers":[],"relativePath":"posts/hello-world.md","filePath":"posts/hello-world.md"}'),r={name:"posts/hello-world.md"};function i(s,t,n,d,c,p){return l(),o("div",null,[...t[0]||(t[0]=[a('<p>一个高中生的博客，第三次开张了。这次总算把想改的都改完了，正式写第一篇。</p><hr><h2 id="自我介绍" tabindex="-1">自我介绍 <a class="header-anchor" href="#自我介绍" aria-label="Permalink to &quot;自我介绍&quot;">​</a></h2><p>这里是柳卿烟，一名高二学生。白天在教室里上课，放学之后的时间基本花在这几件事上：看动画、打游戏、听歌，偶尔折腾一下自己的网站。</p><p>这个博客大概会记录这些内容：</p><ul><li>游戏相关的一些随笔（最近主要在玩 QQ 飞车，偶尔怀旧一下网页游戏）</li><li>追番记录和观后感</li><li>歌单分享</li><li>学习上的复盘和流水账</li><li>折腾网站本身的记录</li></ul><h2 id="站点功能" tabindex="-1">站点功能 <a class="header-anchor" href="#站点功能" aria-label="Permalink to &quot;站点功能&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">功能清单</p><ul><li><strong>搜索</strong>：右上角放大镜，全站文章可以搜</li><li><strong>夜间模式</strong>：右上角开关，切过去看板娘会换睡衣</li><li><strong>看板娘</strong>：左下角的 Live2D 模型，视线会跟着鼠标走，点她会有反应</li><li><strong>评论</strong>：每篇文章底部，GitHub 登录就能发言</li><li><strong>BGM</strong>：右上角音乐按钮，是自己用代码合成的小曲</li><li><strong>RSS</strong>：<code>/rss.xml</code>，欢迎订阅</li></ul></div><h2 id="更新频率" tabindex="-1">更新频率 <a class="header-anchor" href="#更新频率" aria-label="Permalink to &quot;更新频率&quot;">​</a></h2><p>理想状态是每周一更。现实状态大概是：月考周停更，假期多更，周末看情况。</p><p>总之随缘更新，但尽量不断更。</p><hr><p>那么，欢迎来到我的小站。有什么想交流的欢迎评论区留言。</p>',13)])])}const _=e(r,[["render",i]]);export{m as __pageData,_ as default};
